  "summaries": [
    {
      "id": "s_wind_ch4",
      "entity": "known:c03:e_fengxinzi",
      "facet": "风信子·第4章",
      "items": [
        {
          "text": "叙述确认真名南小风；今天是开学前第二天，她在家补暑假作业时被英雄协会紧急通讯叫去绿心公园支援。",
          "refs": [
            "f_wind_realname",
            "f_report_hero_assoc",
            "d4"
          ]
        },
        {
          "text": "半年前离家出走的她遇到自称白灵的观星者精灵，获守护之星后以风信子身份活跃于蓉城，屡次解决英雄协会无法处理的怪人袭击。",
          "refs": [
            "f_wind_obtains_star",
            "f_bailing_is_stargazer",
            "f_wind_active_rongcheng",
            "d17"
          ]
        },
        {
          "text": "她在绿心公园与黑狼怪人战斗并用大剑将其击倒，但怪人随后复活，喷出黑影打飞她的大剑并抓住她。",
          "refs": [
            "f_wind_fights_wolf",
            "f_wind_defeats_wolf",
            "f_wolf_revives",
            "f_wolf_spits_shadow",
            "f_wolf_restrains_wind"
          ]
        },
        {
          "text": "她听到白灵惊问苏天晴“你也是魔法少女”，由此得知眼前的小狐狸似乎也有守护之星、可能是另一位魔法少女。",
          "refs": [
            "f_bailing_asks_su_magical_girl",
            "a_wind_heard_bailing_ask",
            "f_su_has_guardian_star"
          ]
        },
        {
          "text": "她听到苏天晴自称是反派，困惑追问对方身份与蓉城为何还有别的魔法少女。",
          "refs": [
            "f_su_claims_villain",
            "f_wind_asks_identity",
            "f_wind_believes_only_magical_girl"
          ]
        },
        {
          "text": "苏天晴提议玩挠痒痒游戏，称她坚持一分钟不叫出声就放她下来；章末她仍被黑狼控制。",
          "refs": [
            "f_su_proposes_game",
            "f_wolf_restrains_wind",
            "d86"
          ]
        }
      ]
    },
